REPORT demo_reduce_cond_iteration.



CLASS demo DEFINITION.

  PUBLIC SECTION.

    CLASS-METHODS main.

ENDCLASS.



CLASS demo IMPLEMENTATION.

  METHOD main.


    DATA(out) = cl_demo_output=&gt;new(

      )-&gt;next_section( 'Summation'

      )-&gt;write( REDUCE i( INIT sum = 0

                          FOR n = 1 UNTIL n &gt; 10

                          NEXT sum = sum + n )

      )-&gt;next_section( 'Concatenation without THEN'

      )-&gt;write( REDUCE string( INIT text = `Count up:`

                               FOR n = 1 UNTIL n &gt; 10

                 
             NEXT text = text &amp;&amp; | { n }| )

      )-&gt;next_section( 'Concatenation with THEN'

      )-&gt;write( REDUCE string( INIT text = `Count down:`

                 
             FOR n = 10 THEN n - 1 WHILE n &gt; 0

                 
             NEXT text = text &amp;&amp; | { n }| )

      )-&gt;next_section( 'Non arithmetic expression'

      )-&gt;write( REDUCE string( INIT text = ``

                               FOR t = `x` THEN t &amp;&amp; `y`

                 
                         UNTIL strlen( t ) &gt; 10

                 
             NEXT text = text &amp;&amp; |{ t } | )

      )-&gt;display( ).


  ENDMETHOD.

ENDCLASS.



START-OF-SELECTION.

  demo=&gt;main( ).

REPORT demo_data_conversion_structure.



CLASS demo DEFINITION.

  PUBLIC SECTION.

    CLASS-METHODS main.

ENDCLASS.



CLASS demo IMPLEMENTATION.

  METHOD main.




    DATA: BEGIN OF fs1,

             int   TYPE i            VALUE 5,

             pack  TYPE p DECIMALS 2 VALUE '2.26',

             text  TYPE c LENGTH 10  VALUE 'Fine Text',

             float TYPE decfloat16   VALUE '1.234e+05',

             date  TYPE d            VALUE '19950916',

          END OF fs1.



    DATA: BEGIN OF fs2,

             int  TYPE i            VALUE 3,

             pack TYPE p DECIMALS 2 VALUE '72.34',

             text TYPE c LENGTH 5   VALUE 'Hello',

          END OF fs2.



    DATA(out) = cl_demo_output=&gt;new(

      )-&gt;begin_section( 'Source'

      )-&gt;write( |{ fs1-int   width = 10 } {

                   fs1-pack  width = 10 } {

                   fs1-text  width = 10 } {

                   fs1-float width = 10 } {

                   fs1-date  width = 10 }| ).



    out-&gt;next_section( 'Target'

      )-&gt;write( |{ fs2-int  width = 10 } {

                   fs2-pack width = 10 } {

                   fs2-text width = 10 }| ).



    fs2 = fs1.



    out-&gt;next_section( 'Result'

      )-&gt;display( |{ fs2-int  width = 10 } {

                     fs2-pack width = 10 } {

                     fs2-text width = 10 }| ).


  ENDMETHOD.

ENDCLASS.



START-OF-SELECTION.

  demo=&gt;main( ).

REPORT demo_filter_table_condition.



CLASS demo DEFINITION.

  PUBLIC SECTION.

    CLASS-DATA:

      itab TYPE SORTED TABLE OF i WITH NON-UNIQUE KEY table_line,

      ftab TYPE SORTED TABLE OF i WITH NON-UNIQUE KEY table_line.

    CLASS-METHODS:

      main,

      class_constructor.

ENDCLASS.



CLASS demo IMPLEMENTATION.

  METHOD main.


    cl_demo_output=&gt;new(

      )-&gt;next_section( 'itab'

      )-&gt;write( itab

      )-&gt;next_section( 'ftab'

      )-&gt;write( ftab

      )-&gt;next_section(

        'FILTER #( itab IN ftab WHERE table_line = table_line )'

      )-&gt;write(

         FILTER #( itab IN ftab WHERE table_line = table_line )

      )-&gt;next_section(

