REPORT  demo_escape_html.



CLASS demo DEFINITION.

  PUBLIC SECTION.

    CLASS-METHODS main.

ENDCLASS.



CLASS demo IMPLEMENTATION.

  METHOD main.


    DATA: body     TYPE string,

          esc_body TYPE string.



    body = `&lt;table border&gt; `

        &amp;&amp; `&lt;tr&gt;&lt;td&gt;11&lt;/td&gt;&lt;td&gt;12&lt;/td&gt;&lt;/tr&gt; `

        &amp;&amp; `&lt;tr&gt;&lt;td&gt;21&lt;/td&gt;&lt;td&gt;22&lt;/td&gt;&lt;/tr&gt; `

        &amp;&amp; `&lt;/table&gt;`.



    esc_body = escape( val    = body

                       format = cl_abap_format=&gt;e_html_text ).



    cl_demo_output=&gt;new(

      )-&gt;begin_section( 'Original text'

      )-&gt;write_text( body



      )-&gt;next_section( 'Original text formatted as HTML'

      )-&gt;write_html( body



      )-&gt;next_section( 'Escaped text'

      )-&gt;write_text( esc_body



      )-&gt;next_section( 'Escaped text formatted as HTML'

      )-&gt;write_html( esc_body



      )-&gt;display( ).


  ENDMETHOD.

ENDCLASS.



START-OF-SELECTION.

  demo=&gt;main( ).

REPORT demo_sxml_trafo_from_reader.



CLASS sxml_demo DEFINITION.

  PUBLIC SECTION.

    CLASS-METHODS main.

ENDCLASS.



CLASS sxml_demo IMPLEMENTATION.

  METHOD main.



    DATA(xml) = cl_abap_codepage=&gt;convert_to(

      `&lt;document&gt;` &amp;&amp;

      `  &lt;head&gt;` &amp;&amp;

      `    &lt;author&gt;KELLERH&lt;/author&gt;` &amp;&amp;

      `    &lt;date&gt;20120824&lt;/date&gt;` &amp;&amp;

      `  &lt;/head&gt;` &amp;&amp;

      `  &lt;body&gt;` &amp;&amp;

      `    &lt;asx:abap` &amp;&amp;

      `      xmlns:asx=&quot;http://www.sap.com/abapxml&quot; version=&quot;1.0&quot;&gt;` &amp;&amp;

      `      &lt;asx:values&gt;` &amp;&amp;

      `        &lt;TABLE&gt;` &amp;&amp;

      `          &lt;item&gt;1&lt;/item&gt;` &amp;&amp;

      `          &lt;item&gt;2&lt;/item&gt;` &amp;&amp;

      `          &lt;item&gt;3&lt;/item&gt;` &amp;&amp;

      `        &lt;/TABLE&gt;` &amp;&amp;

      `      &lt;/asx:values&gt;` &amp;&amp;

      `    &lt;/asx:abap&gt;` &amp;&amp;

      `  &lt;/body&gt;` &amp;&amp;

      `&lt;/document&gt;` ).



    DATA(reader) =

      CAST if_sxml_reader( cl_sxml_string_reader=&gt;create( xml ) ).



    WHILE reader-&gt;name &lt;&gt; 'body'.

      reader-&gt;next_node( ).

    ENDWHILE.



    DATA itab TYPE TABLE OF i.

    CALL TRANSFORMATION id SOURCE XML reader

                           RESULT table = itab.

    cl_demo_output=&gt;display( itab ).

  ENDMETHOD.

ENDCLASS.



START-OF-SELECTION.

  sxml_demo=&gt;main( ).
